use customer_behaviour;
-- Q1. What is the total revenue generated by male vs female customers?
SELECT gender,sum(purchase_amount) as revenue
from customer_data group by gender;

-- Q2. Which customers used a discount but still spent more than the average purchase amount?
SELECT customer_id,purchase_amount
from customer_data
where discount_applied='Yes' AND purchase_amount>(SELECT avg(purchase_amount) from customer_data);

-- Q3. Which are the Top 5 products with the highest average review rating?
SELECT item_purchased,avg(review_rating) as ratings from customer_data
group by item_purchased
order by avg(review_rating) desc
limit 5;

-- Q4. Compare the average Purchase amount between Standard and Express Shipping?
SELECT shipping_type,avg(purchase_amount) as 'average_amount'
from customer_data
where shipping_type in ('Standard','Express')
group by shipping_type;

-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers?
SELECT subscription_status,count(customer_id),avg(purchase_amount) as 'average_spend', sum(purchase_amount) as 'total_revenue'
from customer_data
group by subscription_status
order by total_revenue desc;

-- Q6. Which 5 products have the highest percentage of purchases with discount applied/
Select item_purchased,Round(sum(CASE when discount_applied='Yes' then 1 else 0 end)/count(*) *100,2) as discount_rate
from customer_data
group by item_purchased
order by discount_rate desc
limit 5;

-- Q7. Segment customers into New,Returning and Loyal based on their total no. of previous purchases and show the count of each segment?
with customer_type as(
	Select customer_id,previous_purchases,
    Case
		When previous_purchases=1 Then "New"
        When previous_purchases between 2 and 10 Then "Returning"
        else "Loyal"
        End as customer_segment
	from customer_data)
select customer_segment,count(*) as "Number of customers"
from customer_type
group by customer_segment;

-- Q8. What are the Top 3 most purchased products within each category?
with item_counts as(
	Select category,item_purchased,count(customer_id) as total_orders,
	ROW_NUMBER() over(partition by category order by count(customer_id) desc) as item_rank
    from customer_data
group by item_purchased,category
)
Select item_rank,category,item_purchased,total_orders from item_counts
where item_rank<=3;

-- Q9. Are customers who are repeated buyers(more than 5 previous purchases) also likely to subscribe?
Select subscription_status, count(customer_id) as repeated_customers
from customer_data
where previous_purchases>5
group by subscription_status;

-- Q10. What is the revenue contribution by each age group?
Select age_group,sum(purchase_amount) as total_revenue
from customer_data
group by age_group
order by total_revenue desc;

